import { L, info, mc, tf, fill, fillc, type, order, match } from '../_h.js';

export default {
  python: [
    L('Values, variables and types',
      info('Start here', 'Python stores **values** in **variables**. Every value has a **type**:\n\n```python\nage = 30          # int\nprice = 9.5       # float\nname = "Mona"     # str\nready = True      # bool\n```\n\nYou never declare the type; Python works it out.'),
      mc('What is the type of `3 / 2` in Python 3?', ['float', 'int', 'str', 'bool'], '`/` always gives a float (1.5). `//` is integer division.'),
      type('What does `7 // 2` evaluate to?', ['3'], 'Floor division drops the fraction.'),
      type('What does `7 % 2` evaluate to?', ['1'], 'The remainder after division.'),
      mc('What does this print?', ['ab3', 'ab + 3', 'Error', '3ab'], 'f-strings insert values into text.', 'x = 3\nprint(f"ab{x}")'),
      fillc('if x > 0 ___ x < 10:\n    print("single digit")', ['and', '&&', 'also', 'plus'], 'Python uses the words and, or, not.'),
      tf('In Python, indentation is part of the syntax.', true, 'Blocks are defined by indentation, not braces.'),
      match('Match the value to its type', [['42', 'int'], ['"42"', 'str'], ['42.0', 'float'], ['None', 'NoneType']])),

    L('Lists, dicts and loops',
      info('Four containers', '```python\nnums = [3, 1, 2]              # list: ordered, changeable\npoint = (2, 5)                # tuple: ordered, fixed\nseen = {"a", "b"}             # set: unique items, fast lookup\nages = {"Mona": 30}           # dict: key -> value\n```\n\nPick by need: order? changes? uniqueness? lookup by key?'),
      type('`nums = [10, 20, 30]`. What is `nums[-1]`?', ['30'], 'Negative indexes count from the end.'),
      type('`nums = [10, 20, 30, 40]`. What is `nums[1:3]`? Write it as a list.', ['[20, 30]', '[20,30]'], 'Slices include the start and exclude the end.'),
      mc('Which container guarantees no duplicates?', ['set', 'list', 'tuple', 'str'], 'Adding an existing item to a set does nothing.'),
      mc('Fastest way to test whether a value is among a million items?', ['Store them in a set and use `in`', 'Store them in a list and use `in`', 'Sort the list each time', 'Loop with an index'], 'Set lookup is O(1) on average; list lookup is O(n).'),
      order('Count how often each word appears', ['counts = {}', 'for w in words:', '    counts[w] = counts.get(w, 0) + 1', 'print(counts)'], '`get` returns 0 the first time a word is seen.'),
      fillc('squares = [x * x ___ x in range(5)]', ['for', 'in', 'if', 'while'], 'A list comprehension builds a list in one line.'),
      type('What is `len({1, 2, 2, 3})`?', ['3'], 'Duplicates collapse in a set.')),

    L('Functions and the standard toolbox',
      info('Functions', '```python\ndef area(w, h=1):\n    return w * h\n```\n\n`h=1` is a **default**. Call `area(3)` or `area(3, h=2)`.\n\nUseful built-ins: `len`, `sum`, `min`, `max`, `sorted`, `enumerate`, `zip`, `range`.'),
      type('With `def area(w, h=1): return w * h`, what is `area(4)`?', ['4'], 'h takes its default value 1.'),
      mc('What does `enumerate(["a", "b"])` produce?', ['Pairs (0, "a"), (1, "b")', 'The list reversed', 'Only the indexes', 'A dict'], 'Index and item together: no manual counter needed.'),
      fillc('ranked = sorted(people, key=lambda p: p["age"], ___=True)', ['reverse', 'desc', 'backwards', 'order'], 'reverse=True sorts from largest to smallest.'),
      info('collections', '```python\nfrom collections import Counter, defaultdict, deque\n\nCounter(words).most_common(3)   # top 3 words\ngroups = defaultdict(list)      # missing keys start as []\nq = deque(); q.append(1); q.popleft()   # fast queue\n```'),
      mc('Which is the idiomatic way to count items?', ['collections.Counter', 'A while loop with indexes', 'A set', 'str.count on a list'], 'Counter is a dict specialised for counting.'),
      mc('What is wrong with `def add(x, items=[]): items.append(x); return items`?', ['The default list is shared between calls', 'Lists cannot be defaults', 'append returns the list', 'Nothing'], 'Defaults are created once. Use `items=None` and create the list inside.'),
      tf('`sorted(xs)` changes the list `xs` in place.', false, '`sorted` returns a new list. `xs.sort()` sorts in place.')),

    L('Generators, performance and interview level',
      info('Lazy values', 'A function with `yield` is a **generator**. It produces one value at a time and pauses in between, so memory stays flat even for huge data.\n\n```python\ndef read_rows(path):\n    for line in open(path):\n        yield line.split(",")\n```'),
      mc('Main advantage of a generator over building a list?', ['It does not hold all items in memory', 'It is always faster', 'It can be indexed', 'It can be reused many times'], 'It is lazy and single-pass.'),
      order('A generator that yields batches', ['def batches(items, size):', '    batch = []', '    for x in items:', '        batch.append(x)', '        if len(batch) == size:', '            yield batch', '            batch = []', '    if batch:', '        yield batch'], 'Do not forget the final, smaller batch.'),
      match('Match the operation to its average cost', [['x in a list', 'O(n)'], ['x in a set', 'O(1)'], ['sorting a list', 'O(n log n)'], ['comparing every pair of items', 'O(n²)']]),
      mc('What does the GIL prevent?', ['Two threads running Python bytecode at the same time', 'Using more than 4 GB of RAM', 'Reading files', 'Calling C libraries'], 'Use processes or vectorised numpy for CPU-bound work.'),
      mc('Which is usually fastest for adding two arrays of a million numbers?', ['numpy: a + b', 'A for loop with append', 'A while loop', 'Recursion'], 'Vectorised operations run in compiled code.'),
      mc('What do `*args` and `**kwargs` collect?', ['Extra positional arguments as a tuple, extra keyword arguments as a dict', 'Pointers', 'Only strings', 'Global variables'], 'They let a function accept any arguments.'),
      order('Order a good answer to a live coding question', ['Restate the problem and ask about edge cases', 'Describe your approach and its complexity', 'Write the code while explaining', 'Test with a normal case and an edge case'], 'Communication is scored as much as the code.'),
      tf('A decorator is a function that takes a function and returns a new one.', true, 'Used for caching, timing, logging, access checks.')),

    L('Classes, errors and context managers',
      info('Classes', 'A **class** bundles data with the functions that work on it.\n\n```python\nclass Account:\n    def __init__(self, owner, balance=0):\n        self.owner = owner\n        self.balance = balance\n\n    def deposit(self, amount):\n        self.balance += amount\n```\n\n`__init__` runs when you create an object. `self` is the object itself.'),
      type('With that class: `a = Account("Sam", 10)` then `a.deposit(5)`. What is `a.balance`?', ['15'], 'The method changes the object’s own balance.'),
      mc('What does the `@dataclass` decorator generate for you?', ['`__init__`, `__repr__` and `__eq__` from the declared fields', 'A database table', 'Type checks at run time', 'A faster interpreter'], 'It removes boilerplate for classes that mainly hold data.'),
      info('Errors and clean-up', 'Code that may fail goes in `try`. Handle the **specific** error you expect:\n\n```python\ntry:\n    value = int(text)\nexcept ValueError:\n    value = 0\nfinally:\n    print("done")     # always runs\n```\n\nA **context manager** (`with`) guarantees clean-up, such as closing a file, even when an error occurs.'),
      fillc('try:\n    value = int(text)\n___ ValueError:\n    value = 0', ['except', 'catch', 'rescue', 'error'], 'Python’s keyword is except.'),
      mc('What does `with open(path) as f:` guarantee?', ['The file is closed even if an error occurs inside the block', 'The whole file is read into memory', 'Errors inside the block are ignored', 'The file is locked for other programs'], 'The context manager runs its clean-up on the way out, error or not.'),
      tf('`except Exception: pass` is a good default because it keeps the program running.', false, 'It hides bugs, so catch the specific error you expect and log the rest.'),
      match('Match the special method to what triggers it', [['__init__', 'Creating an object'], ['__len__', 'Calling len(obj)'], ['__repr__', 'Showing the object in a debugger'], ['__eq__', 'Comparing with ==']]),
      mc('Type hints such as `def f(x: int) -> str:` are…', ['Checked by tools such as mypy, not enforced at run time', 'Enforced by the interpreter', 'Required in every function', 'A way to make code faster'], 'They document intent and let tools find mistakes before the code runs.')),

    L('Common mistakes and debugging',
      info('Names point to objects', 'Assignment never copies. After `b = a`, both names refer to the **same** list, so a change through one is visible through the other.\n\nCopy on purpose: `a.copy()` or `list(a)` for one level, `copy.deepcopy(a)` for nested data.'),
      type('What does this print?', ['3'], 'a and b are the same list.', 'a = [1, 2]\nb = a\nb.append(3)\nprint(len(a))'),
      mc('What does this print?', ['[[1, 0], [1, 0]]', '[[1, 0], [0, 0]]', '[[1, 1], [1, 1]]', 'Error'], 'The outer `* 2` repeats a reference to the same inner list.', 'a = [[0] * 2] * 2\na[0][0] = 1\nprint(a)'),
      info('Equality, identity and floats', '`==` asks "same value?". `is` asks "same object?". Use `is` only for `None`, `True` and `False`.\n\nFloats are binary approximations: `0.1 + 0.2` is `0.30000000000000004`. Compare with `math.isclose(a, b)`, never with `==`.'),
      mc('What does `0.1 + 0.2 == 0.3` evaluate to?', ['False', 'True', 'None', 'It raises an error'], 'Neither side is stored exactly in binary.'),
      fillc('if result ___ None:\n    return default', ['is', '=', 'equals', '==='], '`is None` is the idiomatic identity test.'),
      mc('What does this print?', ['[1, 2, 3]', '[1, 3]', '[1, 2, 2, 3]', 'Error'], 'Removing shifts the items so the loop skips one; build a new list instead.', 'nums = [1, 2, 2, 3]\nfor n in nums:\n    if n == 2:\n        nums.remove(n)\nprint(nums)'),
      order('Order a debugging routine for a failing script', ['Read the last line of the traceback: the error type and message', 'Go to the file and line it names', 'Inspect the variables at that point', 'Form one hypothesis and change one thing', 'Re-run and add a test for the case'], 'One change at a time tells you what fixed it.'),
      tf('Assigning to a variable inside a function changes the global variable of the same name.', false, 'Assignment creates a local name unless you declare it `global`.')),

    L('Case study: a nightly data-cleaning job',
      info('The situation', 'An online retailer exports a 20 GB CSV file of orders every night. A Python script must clean it and load the result before 6:00.\n\nThe first version reads the whole file into a list, crashes with a memory error on some nights and takes hours on others. You are asked to fix it. Make the decisions.'),
      mc('The machine has 8 GB of RAM. How should the script read the file?', ['In chunks, processing one chunk at a time', 'All at once with `f.read()`', 'Into a list of lists first', 'Twice, to be safe'], 'Memory use then depends on the chunk size, not the file size.'),
      fillc('for chunk in pd.read_csv("orders.csv", ___=100_000):\n    process(chunk)', ['chunksize', 'batch', 'rows', 'limit'], 'With chunksize, pandas returns an iterator of DataFrames.'),
      mc('Duplicate order ids are skipped with `if oid not in seen` where `seen` is a list. With 50 million orders this crawls. Fix?', ['Make `seen` a set', 'Sort the list after each append', 'Make `seen` a tuple', 'Add a short sleep'], 'Each membership test drops from O(n) to O(1).'),
      info('Measure before you optimise', 'Do not guess where the time goes. Run a **profiler**:\n\n```\npython -m cProfile -s cumtime clean.py\n```\n\nUsually one or two lines dominate. Fix those, measure again, stop when it is fast enough.'),
      mc('Profiling shows 90% of the time in a Python loop that multiplies two columns row by row. Best fix?', ['Replace the loop with a vectorised column operation', 'Run the loop in several threads', 'Rewrite the whole job in another language', 'Buy more RAM'], 'The multiplication then runs in compiled code.'),
      mc('Parsing is CPU-bound and the machine has 8 cores. Which gives a real speed-up?', ['multiprocessing, with one process per chunk', 'threading, with one thread per chunk', 'async/await', 'A longer timeout'], 'The GIL stops threads from running Python code in parallel, while each process has its own.'),
      mc('One row in ten million has a broken date. What should the job do?', ['Write the row to a rejects file, log it and continue', 'Crash and wait for a human', 'Drop it silently', 'Replace the date with today’s date'], 'The load finishes and nothing is lost or invented.'),
      order('Order the finished job', ['Read the file in chunks', 'Validate and clean each chunk', 'Write bad rows to a rejects file', 'Load the clean chunk into the database', 'Log row counts and the run time'], 'Counts in the log let you prove that every row was loaded or rejected.')),

    L('Interview drill: Python',
      info('What interviewers probe', 'Python questions circle around a few ideas: **mutability**, **hashing**, **scope**, **iterators** and **cost**.\n\nAfter each answer expect a follow-up: "Why?", "What does it cost?", "When does it break?". Answer in one sentence, then give a tiny example.'),
      mc('"What is the difference between a list and a tuple?" Best answer?', ['A tuple is immutable, so it can be a dict key and signals fixed data; a list can change', 'A tuple is always faster and should replace lists', 'Lists hold numbers and tuples hold strings', 'There is no difference'], 'Immutability is the point; the small speed gain is a side effect.'),
      mc('Follow-up: "Can a list be a dict key?"', ['No: keys must be hashable and a mutable list is not', 'Yes, always', 'Only if it is sorted', 'Only if it is empty'], 'If a key could change, its hash would no longer find it.'),
      mc('"Shallow copy versus deep copy?"', ['A shallow copy shares the nested objects; a deep copy duplicates them recursively', 'A shallow copy is slower', 'A deep copy copies only the first level', 'They are the same for nested lists'], 'Changing an inner list through a shallow copy changes the original too.'),
      info('Iterators and closures', 'An **iterable** can hand out an **iterator**; the iterator gives values with `next()` until it raises `StopIteration`. A `for` loop does exactly this.\n\nA **closure** is an inner function that remembers variables of the function that created it. It looks the variable up when it is **called**, not when it is defined.'),
      mc('What does this print?', ['[2, 2, 2]', '[0, 1, 2]', '[0, 0, 0]', 'Error'], 'All three lambdas read the same variable i when called, after the loop has finished.', 'fs = [lambda: i for i in range(3)]\nprint([f() for f in fs])'),
      type('What does `len(list(zip([1, 2, 3], "ab")))` evaluate to?', ['2'], 'zip stops at the shortest input.'),
      match('Match the question to the key phrase of a good answer', [['"How does a dict find a key?"', 'Hashing, O(1) on average'], ['"Why is a generator memory-efficient?"', 'Lazy: one value at a time'], ['"Why do threads not speed up CPU work?"', 'The GIL'], ['"What does a decorator do?"', 'Wraps a function and returns a new one']]),
      order('Order a strong answer to "Explain the GIL"', ['It is a lock that lets only one thread run Python bytecode at a time', 'So threads do not speed up CPU-bound Python code', 'Threads still help with I/O, because the lock is released while waiting', 'For CPU work, use multiprocessing or libraries that run compiled code'], 'Definition, consequence, exception, remedy.'))
  ],

  dsa: [
    L('Counting steps: Big-O',
      info('How fast is fast?', 'We describe speed by how the work grows with input size **n**, ignoring constants. This is **Big-O**.\n\n- **O(1):** same work whatever n is.\n- **O(n):** one pass.\n- **O(n²):** a loop inside a loop.\n- **O(log n):** halving each step.'),
      mc('A single loop over n items is…', ['O(n)', 'O(1)', 'O(n²)', 'O(log n)'], 'Work grows in step with n.'),
      mc('What is the complexity of this code?', ['O(n²)', 'O(n)', 'O(log n)', 'O(1)'], 'n times n pairs.', 'for a in items:\n    for b in items:\n        check(a, b)'),
      type('Binary search halves the range each step. About how many steps for 1,000,000 sorted items?', ['20'], 'log2 of a million is about 20.'),
      match('Match the pattern to its cost', [['Look up a dict key', 'O(1)'], ['Scan a list', 'O(n)'], ['Sort a list', 'O(n log n)'], ['Compare all pairs', 'O(n²)']]),
      mc('n is 100,000. Which is too slow for a one-second limit?', ['O(n²)', 'O(n)', 'O(n log n)', 'O(log n)'], '10 billion operations.'),
      tf('O(2n) and O(n) are the same class.', true, 'Constant factors are dropped.'),
      mc('Space complexity measures…', ['Extra memory used as n grows', 'Lines of code', 'Disk speed', 'Number of functions'], 'Often you trade memory for speed, for example with a hash map.')),

    L('Hash maps and two pointers',
      info('"Have I seen this?"', 'Many O(n²) problems become O(n) with a **hash map** (a dict) or a set: remember what you have seen so you can look it up instantly.\n\nClassic: find two numbers that add to a target. For each number, check whether `target - number` was already seen.'),
      order('Two-sum in one pass', ['seen = {}', 'for j, x in enumerate(nums):', '    if target - x in seen:', '        return [seen[target - x], j]', '    seen[x] = j'], 'Check first, then store, so an element is not paired with itself.'),
      mc('What does the hash map buy us in two-sum?', ['O(n) time instead of O(n²)', 'Less memory', 'Sorted output', 'Nothing'], 'One pass with O(1) lookups, at the cost of O(n) memory.'),
      info('Two pointers', 'On a **sorted** array, put one pointer at each end and move them inward. Each step discards an element, so the whole scan is O(n).\n\nAlso used with a slow and a fast pointer, and as a **sliding window** over a contiguous range.'),
      mc('Sorted array, find a pair with sum 10. The current pair sums to 14. Which pointer moves?', ['The right one, leftwards', 'The left one, rightwards', 'Both outward', 'Neither'], 'The sum is too big, so reduce the larger value.'),
      mc('"Longest substring without repeating characters" is best solved with…', ['A sliding window and a set', 'Sorting the string', 'Trying all substrings', 'Binary search'], 'Grow on the right, shrink on the left when a repeat appears.'),
      mc('Which problem needs a stack?', ['Checking that brackets are balanced', 'Finding the maximum of a list', 'Counting words', 'Summing numbers'], 'The most recent opening bracket must close first: last in, first out.'),
      fillc('if not stack or stack.___() != pairs[ch]:\n    return False', ['pop', 'push', 'peekleft', 'shift'], 'Pop the latest opener and compare.')),

    L('Binary search, heaps and trees',
      info('Binary search', 'On sorted data, look at the middle. If it is too small, discard the left half; too big, discard the right. Repeat.\n\n```python\nlo, hi = 0, len(a) - 1\nwhile lo <= hi:\n    mid = (lo + hi) // 2\n    if a[mid] == x: return mid\n    if a[mid] < x: lo = mid + 1\n    else: hi = mid - 1\n```'),
      mc('Binary search requires the data to be…', ['Sorted', 'Unique', 'Numeric', 'In a dict'], 'Otherwise halving is not valid.'),
      mc('`a[mid]` is smaller than the target. What next?', ['lo = mid + 1', 'hi = mid - 1', 'lo = mid', 'return -1'], 'The target must be to the right. `mid + 1` avoids an infinite loop.'),
      info('Heaps', 'A **heap** always gives you the smallest (or largest) item in O(log n) per push or pop.\n\nUse it for **top-k**, priority queues, and merging sorted lists. In Python: `heapq`.'),
      mc('Keep the 10 largest values from a stream of a billion. Best structure?', ['A min-heap of size 10', 'Sort everything', 'A list scanned each time', 'A dict'], 'Pop the smallest when the heap exceeds 10: O(n log k).'),
      match('Match the structure to its strength', [['Hash map', 'Lookup by key'], ['Heap', 'Smallest or largest item fast'], ['Stack', 'Last in, first out'], ['Queue (deque)', 'First in, first out']]),
      mc('In a binary search tree, an in-order traversal visits nodes…', ['In sorted order', 'In random order', 'Level by level', 'Leaves first'], 'Left subtree, node, right subtree.'),
      tf('BFS on a tree visits it level by level.', true, 'It uses a queue. DFS uses a stack or recursion.')),

    L('Solving under pressure: interview level',
      info('A method, not luck', '1. **Restate** and ask about constraints.\n2. **Example** by hand.\n3. **Brute force** and its complexity.\n4. **Optimise:** which structure removes the bottleneck?\n5. **Code** while talking.\n6. **Test** and state complexity.'),
      order('Order the interview method', ['Clarify inputs, outputs and edge cases', 'Work a small example by hand', 'State a brute-force solution and its cost', 'Optimise with the right data structure', 'Code it, then dry-run a test case'], 'Never start typing in silence.'),
      match('Match the clue to the technique', [['"Sorted array"', 'Binary search or two pointers'], ['"Top k" or "k largest"', 'Heap'], ['"Contiguous subarray"', 'Sliding window'], ['"Shortest path in a grid"', 'BFS'], ['"Count the ways"', 'Dynamic programming']]),
      mc('You are stuck for a minute. Best move?', ['Say what you are thinking and try a smaller example', 'Stay silent until you have the full answer', 'Ask for the solution', 'Start typing random code'], 'Interviewers score reasoning and can only help if they hear it.'),
      mc('Your solution is O(n²) and the interviewer asks "can we do better?" First thing to consider?', ['Whether a hash map or sorting removes the inner loop', 'Rewriting in C', 'Adding threads', 'Using recursion'], 'Most improvements replace a search with a lookup.'),
      mc('Which edge cases should you always test?', ['Empty input, one element, duplicates', 'Only the given example', 'Only large inputs', 'None'], 'They reveal off-by-one and None errors.'),
      mc('Reversing a linked list in place takes…', ['O(n) time and O(1) extra space', 'O(n²) time', 'O(n) extra space always', 'O(log n) time'], 'Three pointers: previous, current, next.'),
      tf('It is acceptable to state the brute-force solution first.', true, 'It shows you understand the problem and gives a baseline to improve.')),

    L('Recursion, linked lists and sorting',
      info('Recursion', 'A **recursive** function calls itself on a smaller input. It needs a **base case** that stops and a step that moves toward it.\n\n```python\ndef depth(node):\n    if node is None:\n        return 0\n    return 1 + max(depth(node.left), depth(node.right))\n```\n\nEvery unfinished call waits on the **call stack**, so deep recursion costs memory.'),
      type('`def f(n): return 1 if n == 0 else n * f(n - 1)`. What is `f(4)`?', ['24'], '4 × 3 × 2 × 1.'),
      mc('A recursive function has no base case. What happens in Python?', ['It raises RecursionError when the call stack is full', 'It returns None', 'It runs for ever without an error', 'It returns 0'], 'Python stops at a depth of about 1,000 calls.'),
      info('Linked lists and sorting', 'A **linked list** is a chain of nodes; each holds a value and a pointer to the next node. Inserting or deleting at a known node is O(1), but reaching the k-th node is O(k).\n\n**Merge sort** splits, sorts each half and merges: O(n log n) always. **Quicksort** partitions around a pivot: O(n log n) on average, O(n²) in the worst case.'),
      match('Match the operation to its cost', [['Read the k-th item of an array', 'O(1)'], ['Reach the k-th node of a linked list', 'O(k)'], ['Merge sort on n items', 'O(n log n)'], ['Quicksort on n items, worst case', 'O(n²)']]),
      mc('Detecting a cycle in a linked list with O(1) extra memory uses…', ['A slow and a fast pointer', 'A hash set of all nodes', 'Sorting the nodes', 'Binary search'], 'If there is a cycle, the fast pointer eventually catches the slow one.'),
      fillc('def merge(a, b):\n    out, i, j = [], 0, 0\n    while i < len(a) and j < len(b):\n        if a[i] <= b[j]:\n            out.append(a[i]); i += 1\n        else:\n            out.append(b[j]); j += 1\n    return out + a[i:] + ___', ['b[j:]', 'b[i:]', 'a[j:]', 'b'], 'Whatever is left of either list is already sorted.'),
      tf('A stable sort keeps equal items in their original order.', true, 'That matters when you sort by one key and then by another.'),
      mc('Prefix sums answer "what is the sum of items i to j?" in…', ['O(1) per query after O(n) preparation', 'O(n) per query', 'O(log n) per query with no preparation', 'O(n²) per query'], 'The answer is the difference of two stored running totals.')),

    L('Common mistakes and debugging',
      info('Off-by-one errors', 'Decide whether your range is **inclusive** or **exclusive** and keep it that way everywhere.\n\n- Inclusive: `lo, hi = 0, len(a) - 1`, loop `while lo <= hi`, move with `hi = mid - 1`.\n- Exclusive: `hi = len(a)`, loop `while lo < hi`, move with `hi = mid`.\n\nMixing the two styles is the most common binary-search bug.'),
      mc('Binary search uses `lo, hi = 0, len(a) - 1` with `while lo < hi`. What goes wrong?', ['It can miss the target when one candidate is left', 'It loops for ever', 'It reads past the end of the array', 'Nothing'], 'With inclusive bounds the last candidate is only checked if the loop runs while lo <= hi.'),
      mc('In binary search you write `lo = mid` instead of `lo = mid + 1`. Result?', ['An infinite loop once lo and hi are next to each other', 'A faster search', 'An immediate index error', 'A sorted array'], 'mid equals lo, so the range stops shrinking.'),
      info('Hidden costs', 'Some innocent lines are O(n): `x in some_list`, `some_list.pop(0)`, `some_list.insert(0, x)`, a slice such as `a[1:]`, and building a string with `+` in a loop.\n\nInside a loop, each of them turns O(n) code into O(n²).'),
      mc('What is the complexity of this code for n items?', ['O(n²)', 'O(n)', 'O(n log n)', 'O(1)'], '`in` on a list is a scan, so keep a set for the membership test.', 'out = []\nfor x in items:\n    if x not in out:\n        out.append(x)'),
      fillc('from collections import deque\nq = deque(items)\nfirst = q.___()   # O(1), unlike list.pop(0)', ['popleft', 'pop_first', 'shift', 'dequeue'], 'A deque removes from either end in constant time.'),
      mc('Your sliding-window code is wrong only for an empty input. Which habit prevents this?', ['Testing empty, single-element and all-equal inputs before you say you are done', 'Wrapping everything in try/except', 'Assuming inputs are never empty', 'Switching to recursion'], 'Edge cases expose off-by-one and None errors.'),
      tf('Adding or deleting keys of a dict while iterating over it raises an error in Python.', true, 'Python raises RuntimeError, so iterate over a copy of the keys.'),
      order('Order a dry run that catches bugs', ['Pick a tiny input of three or four items', 'Write down every variable before the loop', 'Step through one iteration at a time, updating the values', 'Compare the result with the answer worked out by hand', 'Repeat with an empty input and a single item'], 'Tracing by hand finds what staring at the code does not.')),

    L('Case study: search suggestions as you type',
      info('The situation', 'An online shop wants suggestions while the customer types: for the prefix "sho", show the 5 most searched past queries that start with it.\n\nThere are 10 million distinct past queries, each with a search count, and the answer must arrive within 50 ms of every keystroke.'),
      mc('Scanning all 10 million queries on each keystroke is…', ['O(n) per keystroke, which is too slow', 'O(1)', 'O(log n)', 'Fine, because the strings are short'], 'Ten million string comparisons per keystroke will not fit in 50 ms at scale.'),
      info('Two classic structures', 'A **trie** stores strings as paths of characters from a root. All queries sharing a prefix sit below one node, and reaching the node for a prefix of length L costs O(L).\n\nA **sorted array** also works: strings with the same prefix are next to each other, and binary search finds the first in O(log n).'),
      type('In a trie, how many character steps from the root reach the node for the prefix "sho"?', ['3'], 'One step per character.'),
      mc('The node for "sho" has 200,000 queries below it. How do you return the top 5 without sorting them on every request?', ['Precompute the top 5 and store them at each node', 'Sort the 200,000 on every keystroke', 'Return the first 5 alphabetically', 'Return 5 at random'], 'The work is done once at build time, trading memory for speed.'),
      mc('While building those lists, which structure keeps the 5 largest counts as you scan a node’s queries?', ['A min-heap of size 5', 'A max-heap of every query', 'A stack', 'A linked list'], 'Pop the smallest whenever the heap grows beyond 5.'),
      mc('A few short prefixes such as "s" and "i" make up most requests. Cheap extra win?', ['Cache the answers for the most frequent prefixes in a hash map', 'Delete those prefixes', 'Make the trie deeper', 'Sort more often'], 'A cache answers the hot cases in one lookup.'),
      tf('Storing a top-5 list at every node costs extra memory in exchange for faster lookups.', true, 'This time-for-memory trade is the heart of most precomputation.'),
      order('Order your explanation to the interviewer', ['State the requirement: top 5 per prefix within 50 ms', 'Reject the full scan and say why', 'Propose a trie with a precomputed top 5 per node', 'Give the costs: O(L) per lookup and extra memory', 'Add a cache for hot prefixes and a plan for updating counts'], 'Requirement, baseline, design, cost, extensions.')),

    L('Interview drill: data structures',
      info('The questions behind the questions', 'Interviewers reuse a small set of patterns. After your first solution expect:\n\n- "What is the time and space complexity?"\n- "Can you do better?"\n- "What if the input does not fit in memory?"\n- "What if it arrives as a stream?"'),
      mc('"How does a hash map work?" Best answer?', ['A hash function maps the key to a bucket, collisions are handled by chaining or probing, and the table grows as it fills', 'It keeps the keys sorted and uses binary search', 'It stores the keys in a linked list and scans it', 'It compresses the keys'], 'Function, collisions, resizing: the three parts they listen for.'),
      mc('Follow-up: "What is the worst-case lookup in a hash map?"', ['O(n), when many keys collide', 'O(1), always', 'O(log n), always', 'O(n²)'], 'O(1) is the average case with a good hash function.'),
      mc('"Find the k-th largest of n numbers." Which answer shows the trade-offs?', ['Sort in O(n log n), or keep a min-heap of size k in O(n log k), or use quickselect in O(n) on average', 'Sorting is the only way', 'Remove the maximum k times, which is always best', 'Use a hash map'], 'Offering several options with their costs is what scores.'),
      info('Stating complexity well', 'Say what **n** is. Give **time and space**. Mention average against worst case when they differ, as for hash maps and quicksort. Count the **recursion stack** as space.'),
      mc('A recursive DFS on a tree of height h uses how much extra space?', ['O(h) for the call stack', 'O(1)', 'O(h²)', 'None, because recursion is free'], 'One stack frame per level of the current path.'),
      type('Merging k sorted lists with n items in total, using a heap, costs O(n log ___). Which letter fills the gap?', ['k', 'K'], 'The heap holds one item per list.'),
      match('Match the follow-up to a good reply', [['"What if the data does not fit in memory?"', 'Process in chunks; external merge sort'], ['"What if it arrives as a stream?"', 'Keep a running summary such as a heap or counter'], ['"What if the array is already sorted?"', 'Binary search or two pointers'], ['"What if there are many queries?"', 'Precompute an index or prefix sums']]),
      order('Order a strong answer to "Array or linked list?"', ['Arrays give O(1) access by index and are cache-friendly', 'Linked lists give O(1) insert and delete at a known node', 'But reaching that node in a linked list is O(n)', 'So I default to arrays and use a deque or linked list for frequent changes at the ends'], 'Strengths of each, the catch, then your default.'))
  ],

  'algo-advanced': [
    L('Graphs and how to walk them',
      info('Nodes and edges', 'A **graph** is a set of nodes connected by edges: cities and roads, pages and links, grid cells and their neighbours.\n\nStore it as an **adjacency list**: for each node, the list of its neighbours.\n\n```python\ngraph = {"A": ["B", "C"], "B": ["D"], "C": ["D"], "D": []}\n```'),
      mc('In a grid where you move up, down, left, right, each cell has at most how many neighbours?', ['4', '2', '8', '1'], 'One per direction.'),
      info('BFS and DFS', '**BFS** explores in layers using a **queue**: all nodes 1 step away, then 2, then 3.\n\n**DFS** follows one path as deep as possible using a **stack** or recursion, then backtracks.\n\nBoth must remember **visited** nodes or they loop for ever.'),
      match('Match the search to its data structure', [['BFS', 'Queue'], ['DFS', 'Stack or recursion'], ['Dijkstra', 'Min-heap'], ['A*', 'Min-heap ordered by cost plus heuristic']]),
      mc('Which finds the shortest path in an unweighted graph?', ['BFS', 'DFS', 'Neither', 'Sorting'], 'The first time BFS reaches a node is by a shortest route.'),
      order('BFS from a start node', ['dist = {start: 0}', 'queue = deque([start])', 'while queue:', '    node = queue.popleft()', '    for nxt in graph[node]:', '        if nxt not in dist:', '            dist[nxt] = dist[node] + 1', '            queue.append(nxt)'], 'Mark a node when you add it, not when you pop it.'),
      mc('What happens if you forget the visited check on a graph with a cycle?', ['The search never ends', 'It runs faster', 'It returns the wrong start', 'Nothing'], 'It keeps re-adding the same nodes.'),
      tf('DFS is a natural fit for detecting cycles and topological sorting.', true, 'It tracks the current path.')),

    L('Weighted paths: Dijkstra and A*',
      info('When steps have different costs', 'If edges have weights (distance, time), BFS is wrong: fewer edges is not the same as lower cost.\n\n**Dijkstra** always expands the unvisited node with the smallest known distance, using a **min-heap**.'),
      mc('Why does Dijkstra use a min-heap?', ['To get the closest unsettled node quickly', 'To sort the output', 'To save memory', 'To detect cycles'], 'Each pop gives the next node whose distance is final.'),
      order('The core of Dijkstra', ['dist = {source: 0}', 'heap = [(0, source)]', 'while heap:', '    d, node = heapq.heappop(heap)', '    for nxt, w in graph[node]:', '        if d + w < dist.get(nxt, inf):', '            dist[nxt] = d + w', '            heapq.heappush(heap, (d + w, nxt))'], 'Relax each edge: keep the shorter distance.'),
      mc('Dijkstra gives wrong answers when…', ['Some edge weights are negative', 'The graph has cycles', 'There are many nodes', 'Weights are floats'], 'A settled node could later be improved. Use Bellman-Ford.'),
      info('A*', '**A-star** adds a **heuristic**: an estimate of the remaining distance to the goal, such as straight-line distance. It expands nodes by `cost so far + estimate`.\n\nIf the heuristic never overestimates, the result is still optimal, with far fewer nodes expanded.'),
      mc('A good A* heuristic for a grid with 4-direction moves is…', ['Manhattan distance to the goal', 'A random number', 'Always 1000', 'The number of walls'], 'It never overestimates the true distance.'),
      mc('With a heuristic of 0 everywhere, A* behaves like…', ['Dijkstra', 'DFS', 'Binary search', 'A random walk'], 'Only the cost so far remains.'),
      tf('A* is widely used in robot and vehicle path planning.', true, 'It searches toward the goal instead of in all directions.')),

    L('Dynamic programming',
      info('Remember, do not recompute', 'Some problems break into smaller problems that **repeat**. Solve each once and store the answer.\n\nFibonacci by plain recursion recomputes the same values exponentially often. With a table it is linear.'),
      type('fib(0)=0, fib(1)=1, fib(n)=fib(n-1)+fib(n-2). What is fib(6)?', ['8'], '0, 1, 1, 2, 3, 5, 8.'),
      mc('Two signs that dynamic programming applies?', ['Overlapping subproblems and optimal substructure', 'Sorted input and unique values', 'A graph and a heap', 'Strings and recursion'], 'Repeated subproblems, and best answers built from smaller best answers.'),
      order('The DP recipe', ['Define the state: what does dp[i] mean?', 'Write the transition from smaller states', 'Set the base cases', 'Choose the order of computation', 'Read the answer from the table'], 'Most of the work is defining the state.'),
      info('Coin change', 'Fewest coins to make an amount. Let `best[a]` be the answer for amount `a`:\n\n```\nbest[a] = 1 + min(best[a - c] for each coin c <= a)\n```\n\nGreedy (always the largest coin) fails: coins 1, 3, 4 and amount 6 need 3+3, not 4+1+1.'),
      type('Coins 1, 3, 4. Fewest coins to make 6?', ['2'], '3 + 3.'),
      fillc('for a in range(1, amount + 1):\n    for c in coins:\n        if c <= a:\n            best[a] = min(best[a], best[a - c] + ___)', ['1', 'c', 'a', '0'], 'One more coin than the best way to make the remainder.'),
      match('Match the classic DP problem to its state', [['Longest common subsequence', 'dp[i][j]: best for the first i and j characters'], ['Knapsack', 'dp[w]: best value within weight w'], ['Coin change', 'dp[a]: fewest coins for amount a'], ['Climbing stairs', 'dp[i]: ways to reach step i']])),

    L('Putting it together: interview level',
      info('Where these live in AI systems', '- **A-star** and Dijkstra: path planning.\n- **Hungarian algorithm:** assign detections to tracks at minimum total cost.\n- **Longest common subsequence:** the ROUGE-L text metric.\n- **Viterbi / beam search:** decoding sequences.\n- **Union-find:** grouping connected detections.'),
      mc('Matching radar detections to existing tracks with minimum total distance is which problem?', ['Assignment (Hungarian algorithm)', 'Shortest path', 'Sorting', 'Knapsack'], 'A one-to-one minimum-cost matching.'),
      mc('ROUGE-L is computed with which DP?', ['Longest common subsequence', 'Coin change', 'Knapsack', 'Fibonacci'], 'It rewards words in the same order, not necessarily adjacent.'),
      mc('Top-down memoisation versus bottom-up tabulation?', ['Same idea: recursion with a cache, or filling a table iteratively', 'Tabulation is always exponential', 'Memoisation needs no base cases', 'They solve different problems'], 'Bottom-up avoids recursion limits and often saves memory.'),
      mc('A DP has n × m states and each takes O(1). Its time complexity?', ['O(n·m)', 'O(n + m)', 'O(2ⁿ)', 'O(log n)'], 'States times work per state.'),
      order('Order a strong answer to "Solve this DP problem"', ['Describe the brute-force recursion', 'Point out the repeated subproblems', 'Define the state and transition', 'Implement with a table and state the complexity'], 'Show how you get there, not just the table.'),
      mc('Minimum number of moves between two cells in a maze. Which algorithm?', ['BFS', 'DFS', 'Dijkstra with random weights', 'Binary search'], 'Every move costs the same.'),
      tf('Greedy algorithms always give the optimal answer.', false, 'Only when the problem has the greedy-choice property. Coin change with arbitrary coins does not.'),
      mc('Topological sort applies to…', ['Directed graphs without cycles', 'Any graph', 'Only trees', 'Sorted arrays'], 'For example ordering tasks by dependency.')),

    L('Topological sort, union-find and backtracking',
      info('Topological sort', 'Tasks with dependencies form a **directed acyclic graph**. A **topological order** lists every task after the tasks it depends on.\n\n**Kahn’s algorithm:** count the incoming edges of each node, then repeatedly take a node with none, output it, and lower the count of its neighbours.'),
      order('Kahn’s algorithm', ['Count the incoming edges of every node', 'Put all nodes with zero incoming edges in a queue', 'Pop a node and append it to the output', 'Lower the count of each of its neighbours by one', 'Add any neighbour whose count reached zero to the queue'], 'If the output is shorter than the number of nodes, the graph has a cycle.'),
      mc('Edges A→B, A→C, B→D, C→D. Which is a valid topological order?', ['A, C, B, D', 'B, A, C, D', 'D, B, C, A', 'A, D, B, C'], 'A comes first, D last, and B and C may come in either order.'),
      info('Union-find', '**Union-find** (disjoint sets) tracks which items belong to the same group. `find(x)` returns the representative of x’s group; `union(a, b)` merges two groups. With path compression both are almost O(1).\n\nUses: connected components, cycle detection in undirected graphs, Kruskal’s minimum spanning tree.'),
      fillc('def find(x):\n    if parent[x] != x:\n        parent[x] = ___(parent[x])   # path compression\n    return parent[x]', ['find', 'union', 'len', 'max'], 'Every node on the path is re-attached directly to the root.'),
      type('Nodes 1 to 5 start alone. After union(1, 2), union(3, 4) and union(2, 3), how many groups remain?', ['2'], 'The groups are {1, 2, 3, 4} and {5}.'),
      mc('Trying a choice, recursing, and undoing the choice if it fails (N-queens, Sudoku) is called…', ['Backtracking', 'Greedy search', 'Memoisation', 'Hashing'], 'It is a depth-first search over partial solutions.'),
      match('Match the problem to the algorithm', [['Order courses by prerequisites', 'Topological sort'], ['Cheapest network connecting all sites', 'Minimum spanning tree (Kruskal)'], ['Shortest paths with negative edge weights', 'Bellman-Ford'], ['All solutions to a puzzle', 'Backtracking']]),
      tf('Kruskal’s algorithm uses union-find to skip edges that would create a cycle.', true, 'An edge whose two ends are already in the same group is rejected.')),

    L('Common mistakes and debugging',
      info('Graph bugs', '- Marking a node visited when it is **popped** instead of when it is **pushed**: the same node enters the queue many times.\n- Forgetting that a graph may be **disconnected**: start a search from every unvisited node.\n- Recursive DFS on a long chain: Python’s recursion limit of about 1,000 is hit.'),
      mc('A recursive DFS crashes with RecursionError on a path of 100,000 nodes. Best fix?', ['Rewrite it with an explicit stack', 'Remove the visited set', 'Catch the error and continue', 'Sort the nodes first'], 'An explicit stack lives on the heap and has no depth limit.'),
      mc('Dijkstra pushes a node again each time its distance improves. What do you do when you pop an entry whose distance is larger than the best known one?', ['Skip it, because it is stale', 'Process it again', 'Raise an error', 'Reset all distances'], 'Processing outdated entries wastes work on large graphs.'),
      fillc('d, node = heapq.heappop(heap)\nif d > dist[node]:\n    ___', ['continue', 'break', 'return', 'pass'], '`break` would abandon the valid entries still in the heap.'),
      info('Dynamic-programming bugs', '- **Wrong base case:** for coin change, `best[0]` must be 0 and unreachable amounts must start at infinity.\n- **Wrong loop order:** in 0/1 knapsack with a 1-D table, loop the weight **downwards**, or an item is used twice.\n- **Incomplete cache key:** the memo must be keyed by the full state.'),
      mc('0/1 knapsack with a 1-D table and the weight loop running upwards. Effect?', ['Each item can be taken several times', 'Items are never taken', 'An index error', 'No effect'], 'Going upwards reads values already updated for the same item.'),
      mc('A memoised recursion is still exponentially slow. First check?', ['That the cache is really read and written, with the full state as its key', 'That the recursion is deep enough', 'That the input is sorted', 'That the function has a docstring'], 'A cache that is never hit changes nothing.'),
      mc('Your A* returns a path longer than the true shortest path. Likely cause?', ['The heuristic overestimates the remaining cost', 'The heuristic is zero', 'The heap is too small', 'The graph has too few nodes'], 'An inadmissible heuristic can make A* settle for a worse path.'),
      tf('In a grid search in Python, a missing bounds check can silently read the opposite edge through index -1.', true, 'Negative indexes count from the end, so no error is raised.')),

    L('Case study: route planning for deliveries',
      info('The situation', 'A parcel-delivery company needs driving routes between depots and customers. The road network is a graph: 2 million junctions (nodes) and 5 million road segments (edges), each with a travel time in seconds.\n\nA route request must be answered in well under a second.'),
      mc('A one-way street is modelled as…', ['A directed edge', 'An undirected edge', 'Two nodes without an edge', 'A negative weight'], 'Direction is part of the edge.'),
      mc('Segments have different travel times. Which algorithm is the correct baseline for the fastest route?', ['Dijkstra', 'BFS', 'DFS', 'Topological sort'], 'BFS would minimise the number of segments, not the time.'),
      mc('Dijkstra explores in every direction from the depot. What focuses the search on the destination?', ['A* with a heuristic', 'A larger heap', 'Sorting the edges first', 'Running DFS first'], 'The heuristic ranks nodes that lead toward the goal first.'),
      mc('The cost is travel time. Which heuristic never overestimates?', ['Straight-line distance divided by the highest legal speed', 'Straight-line distance divided by walking speed', 'The number of junctions left times 60 seconds', 'A constant 3,600 seconds'], 'No route can be faster than the straight line at top speed.'),
      info('Making it production-ready', 'Real routing systems add three things:\n\n- **Precomputed shortcuts** between important junctions, so a query touches few nodes.\n- **Live edge weights** from traffic data.\n- A separate optimiser for the **order of stops**, which is a travelling-salesman-type problem solved with heuristics.'),
      mc('Traffic changes edge weights every minute. Consequence for precomputed shortcuts?', ['They go stale and must be refreshed or corrected at query time', 'Nothing changes', 'They become more accurate', 'The graph gains nodes'], 'Precomputation assumes the weights it was built from.'),
      mc('A van must visit 30 addresses. Trying every order means 30! possibilities. Realistic approach?', ['A heuristic such as nearest neighbour followed by local improvement', 'Enumerate all orders', 'Run Dijkstra once', 'Binary search over the orders'], 'Exact search is hopeless at this size, and good heuristics come within a few percent.'),
      order('Order the design you would present', ['Model junctions as nodes and road segments as weighted directed edges', 'Start with Dijkstra as a correct baseline', 'Switch to A* with an admissible travel-time heuristic', 'Add precomputed shortcuts for speed', 'Refresh edge weights from live traffic'], 'Correct first, then fast, then current.')),

    L('Interview drill: graphs and dynamic programming',
      info('What gets asked', '"BFS or DFS, and why?" "Why does Dijkstra fail with negative weights?" "Top-down or bottom-up?" "What is your state?"\n\nExpect a complexity follow-up every time. For graphs, give it in **V** (nodes) and **E** (edges).'),
      mc('Time complexity of BFS or DFS on a graph stored as an adjacency list?', ['O(V + E)', 'O(V × E)', 'O(V²) always', 'O(log V)'], 'Every node and every edge is handled once.'),
      mc('Time complexity of Dijkstra with a binary heap?', ['O((V + E) log V)', 'O(V + E)', 'O(V³)', 'O(E²)'], 'Each heap operation costs log V.'),
      mc('"When would you choose DFS over BFS?"', ['When you must follow whole paths: cycle detection, topological order, backtracking', 'When you need the shortest path in an unweighted graph', 'When edges have weights', 'Never'], 'BFS is for layers and shortest hop counts.'),
      info('Explaining a DP out loud', 'Say the **state** in one sentence ("dp[i] is the best answer using the first i items"), then the **transition**, the **base case** and the **complexity** as states × work per state.\n\nIf each row only reads the previous row, mention that memory can be cut to one or two rows.'),
      type('You may climb 1 or 2 stairs at a time. ways(1) = 1 and ways(2) = 2. What is ways(5)?', ['8'], 'The sequence is 1, 2, 3, 5, 8.'),
      mc('Follow-up: "Your table is n × m, but each row only reads the row above. Improvement?"', ['Keep two rows, which needs O(m) memory', 'Nothing can be saved', 'Use recursion without a cache', 'Sort the table'], 'Rows that are never read again can be discarded.'),
      match('Match the question to the core of the answer', [['"Why does Dijkstra fail with negative edges?"', 'A settled node could still be improved later'], ['"Why is A* optimal?"', 'The heuristic never overestimates'], ['"Why does greedy fail for coin change?"', 'A locally best coin can block the best total'], ['"Why does BFS find shortest paths?"', 'It reaches nodes in order of edge count']]),
      order('Order a strong answer to "BFS or DFS?"', ['Both visit every node and edge once: O(V + E)', 'BFS uses a queue and finds shortest paths in unweighted graphs', 'DFS uses a stack and suits cycle detection and topological sort', 'BFS can need more memory on wide graphs, DFS on deep ones', 'So I choose by what the problem asks for'], 'Common ground, each one’s strength, the cost, the decision.'))
  ],

  sql: [
    L('Asking a table questions',
      info('Tables and SELECT', 'A database stores data in **tables**: rows are records, columns are fields.\n\n```sql\nSELECT name, salary\nFROM employees\nWHERE dept = \'ML\'\nORDER BY salary DESC\nLIMIT 5;\n```\n\nRead it as: from this table, keep these rows, show these columns, in this order.'),
      order('Order the clauses of a basic query', ['SELECT name, salary', 'FROM employees', "WHERE dept = 'ML'", 'ORDER BY salary DESC', 'LIMIT 5;'], 'SELECT, FROM, WHERE, ORDER BY, LIMIT.'),
      mc('Which clause filters rows?', ['WHERE', 'SELECT', 'ORDER BY', 'LIMIT'], 'WHERE keeps only rows that match the condition.'),
      fillc("SELECT * FROM employees WHERE salary ___ 40000 AND 60000;", ['BETWEEN', 'INSIDE', 'RANGE', 'WITHIN'], 'BETWEEN includes both ends.'),
      mc('How do you test for a missing value?', ['WHERE manager IS NULL', 'WHERE manager = NULL', 'WHERE manager == None', 'WHERE manager = ""'], 'NULL is not equal to anything, even itself. Use IS NULL.'),
      mc('`SELECT DISTINCT dept FROM employees` returns…', ['Each department once', 'All rows', 'The number of departments', 'The first department'], 'DISTINCT removes duplicate rows from the result.'),
      fillc("SELECT name FROM employees WHERE name ___ 'M%';", ['LIKE', 'MATCH', '==', 'STARTS'], '% matches any sequence of characters.'),
      tf('`ORDER BY salary DESC` puts the highest salary first.', true, 'ASC (the default) is smallest first.')),

    L('Summarising with GROUP BY',
      info('Aggregates', '`COUNT`, `SUM`, `AVG`, `MIN`, `MAX` collapse many rows into one value.\n\n`GROUP BY` does it once per group:\n\n```sql\nSELECT dept, COUNT(*) AS n, AVG(salary) AS avg_salary\nFROM employees\nGROUP BY dept;\n```'),
      mc('What does `SELECT COUNT(*) FROM employees` return?', ['One row with the number of employees', 'All employees', 'The column names', 'An error'], 'An aggregate without GROUP BY gives a single row.'),
      mc('You want only departments with more than 5 people. Which clause?', ['HAVING COUNT(*) > 5', 'WHERE COUNT(*) > 5', 'LIMIT 5', 'ORDER BY 5'], 'WHERE runs before grouping; HAVING filters the groups.'),
      order('Order the clauses with grouping', ['SELECT dept, AVG(salary)', 'FROM employees', 'WHERE salary > 0', 'GROUP BY dept', 'HAVING COUNT(*) >= 2', 'ORDER BY 2 DESC;'], 'WHERE before GROUP BY, HAVING after.'),
      match('Match the clause to when it filters', [['WHERE', 'Rows, before grouping'], ['HAVING', 'Groups, after aggregation'], ['LIMIT', 'The final result'], ['DISTINCT', 'Duplicate output rows']]),
      mc('`COUNT(*)` versus `COUNT(manager)`?', ['COUNT(manager) ignores rows where manager is NULL', 'They are always equal', 'COUNT(*) ignores NULLs', 'COUNT(manager) counts distinct values'], 'Aggregates skip NULLs; COUNT(*) counts rows.'),
      mc('Every column in SELECT that is not inside an aggregate must…', ['Appear in GROUP BY', 'Be numeric', 'Be the primary key', 'Be renamed'], 'Otherwise the database cannot know which value to show for the group.'),
      type('A table has salaries 10, 20, NULL. What does AVG(salary) return?', ['15', '15.0'], 'NULL is ignored: (10 + 20) / 2.')),

    L('Joins',
      info('Combining tables', 'Data is split across tables and linked by keys. A **join** puts rows together.\n\n```sql\nSELECT c.name, o.amount\nFROM customers c\nJOIN orders o ON o.customer_id = c.id;\n```\n\n**INNER JOIN** keeps only matches. **LEFT JOIN** keeps every left row, with NULLs when nothing matches.'),
      mc('Customers who have never ordered disappear from the result with…', ['INNER JOIN', 'LEFT JOIN from customers', 'FULL OUTER JOIN', 'No join does that'], 'Inner join keeps only matching pairs.'),
      order('Find customers with no orders', ['SELECT c.name', 'FROM customers c', 'LEFT JOIN orders o ON o.customer_id = c.id', 'WHERE o.id IS NULL;'], 'Keep all customers, then keep those where the order side is empty.'),
      type('customers has 3 rows. Customer A has 2 orders, B has 1, C has 0. How many rows does an INNER JOIN return?', ['3'], '2 + 1 + 0.'),
      type('Same data. How many rows does a LEFT JOIN from customers return?', ['4'], '2 + 1 + 1 row for C with NULLs.'),
      mc('A join suddenly returns far more rows than expected. Likely cause?', ['The join key is not unique on one side, so rows multiply', 'Too many columns', 'A missing ORDER BY', 'A slow disk'], 'Check key uniqueness before joining; it silently inflates sums.'),
      match('Match the join', [['INNER', 'Only rows that match on both sides'], ['LEFT', 'All left rows, matched or not'], ['FULL OUTER', 'All rows from both sides'], ['CROSS', 'Every combination of rows']]),
      tf('Putting a condition on the right table in WHERE can turn a LEFT JOIN into an INNER JOIN.', true, 'It removes the NULL rows. Put such conditions in the ON clause.')),

    L('Window functions and interview level',
      info('Calculating across rows without collapsing them', 'A **window function** computes over related rows and keeps every row:\n\n```sql\nSELECT name, dept, salary,\n       RANK() OVER (PARTITION BY dept ORDER BY salary DESC) AS r\nFROM employees;\n```\n\n`PARTITION BY` defines the group, `ORDER BY` the order within it.'),
      mc('Salaries 100, 100, 90. What does DENSE_RANK() give?', ['1, 1, 2', '1, 1, 3', '1, 2, 3', '2, 2, 3'], 'RANK would give 1, 1, 3. ROW_NUMBER gives 1, 2, 3.'),
      order('Top earner per department', ['SELECT dept, name, salary', 'FROM (', '  SELECT *, DENSE_RANK() OVER (PARTITION BY dept ORDER BY salary DESC) AS r', '  FROM employees', ') t', 'WHERE r = 1;'], 'You cannot filter on a window function in the same level, so wrap it.'),
      fillc('SELECT day, sales - ___(sales) OVER (ORDER BY day) AS change FROM daily;', ['LAG', 'PREV', 'BEFORE', 'SHIFT'], 'LAG reads the previous row; LEAD the next.'),
      mc('`SUM(amount) OVER (ORDER BY day)` computes…', ['A running total', 'The grand total on every row', 'The daily average', 'A ranking'], 'With ORDER BY the window grows row by row.'),
      mc('A CTE (`WITH x AS (...)`) is mainly for…', ['Naming a sub-query to make the query readable', 'Creating a permanent table', 'Speeding up every query', 'Deleting rows'], 'It lets you build a query in steps.'),
      mc('A query filtering on `user_id` is slow on a large table. First check?', ['Whether an index exists on user_id (read the plan with EXPLAIN)', 'The font size', 'Add ORDER BY', 'Use SELECT *'], 'An index turns a full scan into a lookup.'),
      order('Order a strong approach to a live SQL question', ['Restate the question and look at the table columns', 'Decide the grain: one row per what?', 'Build it in steps: join, filter, aggregate', 'Check edge cases: NULLs, ties, duplicates'], 'Stating the grain prevents most mistakes.'),
      tf('`WHERE` cannot refer to a window function defined in the same SELECT.', true, 'Window functions are computed after WHERE. Use a sub-query or CTE.')),

    L('Subqueries, set operations and transactions',
      info('Subqueries and CASE', '```sql\nSELECT name, salary,\n       CASE WHEN salary >= 50000 THEN \'high\' ELSE \'normal\' END AS band\nFROM employees\nWHERE salary > (SELECT AVG(salary) FROM employees);\n```\n\nA **subquery** is a query inside a query. `CASE` is SQL’s if/else. `EXISTS (subquery)` is true when the subquery returns at least one row.'),
      mc('`SELECT name FROM employees WHERE salary > (SELECT AVG(salary) FROM employees)` returns…', ['Employees paid above the overall average', 'The average salary', 'All employees', 'An error, because aggregates cannot be nested'], 'The inner query yields one number that the outer query compares against.'),
      fillc('SELECT COUNT(CASE WHEN status = \'late\' THEN 1 ___) AS n_late FROM orders;', ['END', 'DONE', 'FI', 'CLOSE'], 'Rows that do not match give NULL, which COUNT ignores.'),
      mc('UNION versus UNION ALL?', ['UNION removes duplicate rows; UNION ALL keeps them and is faster', 'UNION ALL removes duplicates', 'They are identical', 'UNION places columns side by side'], 'Removing duplicates needs an extra sort or hash step.'),
      type('Table A holds the values 1, 2, 2 and table B holds 2, 3. How many rows does `SELECT v FROM A UNION SELECT v FROM B` return?', ['3'], 'The distinct values are 1, 2 and 3.'),
      info('Transactions and keys', 'A **transaction** groups statements so that all succeed or none do: `BEGIN; ... COMMIT;` or `ROLLBACK;`. The guarantees are called **ACID**.\n\nA **primary key** identifies each row. A **foreign key** points to the primary key of another table.'),
      match('Match the ACID property', [['Atomic', 'All statements happen or none do'], ['Consistent', 'Constraints hold before and after'], ['Isolated', 'Concurrent transactions do not interfere'], ['Durable', 'Committed data survives a crash']]),
      mc('A transfer debits one account and credits another. Why wrap both in one transaction?', ['So a failure between them cannot leave money debited but not credited', 'To make the statements faster', 'To avoid writing a WHERE clause', 'Because UPDATE requires it'], 'Atomicity makes the pair one indivisible step.'),
      tf('Normalisation reduces duplicated data by splitting it into related tables.', true, 'Analytics tables are often denormalised again for faster reads.')),

    L('Common mistakes and debugging',
      info('NULL surprises', 'NULL means "unknown". Any comparison with NULL gives unknown, and WHERE keeps only rows that are true.\n\n- `WHERE x <> 5` drops rows where x is NULL.\n- `x NOT IN (1, NULL)` is never true.\n- `NULL + 1` is NULL.\n\nUse `IS NULL`, `COALESCE(x, 0)` and `NOT EXISTS`.'),
      type('A column holds 5, 7 and NULL. How many rows does `WHERE x <> 5` return?', ['1'], 'Only 7, because the comparison with NULL is unknown.'),
      mc('`WHERE id NOT IN (SELECT manager_id FROM employees)` returns no rows, although some people manage nobody. Why?', ['manager_id contains a NULL, so NOT IN is never true', 'NOT IN is not valid SQL', 'The table is locked', 'The subquery returns too many rows'], 'Use NOT EXISTS or filter the NULLs out of the subquery.'),
      fillc('SELECT ___(discount, 0) AS discount FROM orders;', ['COALESCE', 'NULLSAFE', 'DEFAULT', 'REPLACE'], 'COALESCE returns its first argument that is not NULL.'),
      info('Fan-out and double counting', 'Join `orders` to `order_items` and then `SUM(orders.shipping_fee)`: an order with 3 items has its fee counted 3 times.\n\nThe join changed the **grain** from one row per order to one row per item. Aggregate each table to the same grain first, then join.'),
      type('An order has a shipping fee of 10 and 3 item rows. After joining orders to items, what does SUM(shipping_fee) give for that order?', ['30'], 'The fee is repeated on each of the 3 joined rows.'),
      mc('How do you fix that double counting?', ['Aggregate the items per order in a subquery, then join one row per order', 'Add DISTINCT to the SELECT list', 'Use a CROSS JOIN', 'Sort by order id'], 'Both sides then have the same grain.'),
      mc('`SELECT dept, name, MAX(salary) FROM employees GROUP BY dept` is wrong because…', ['name is neither grouped nor aggregated, so its value is undefined or an error', 'MAX cannot be used with GROUP BY', 'dept must be numeric', 'A HAVING clause is missing'], 'Use a window function to get the row that holds the maximum.'),
      mc('In many databases, `SELECT 1 / 2` returns…', ['0', '0.5', 'NULL', 'An error'], 'Both operands are integers, so cast one side or multiply by 1.0.')),

    L('Case study: a retention report',
      info('The situation', 'A subscription app wants a retention report: of the users who signed up in a given week, what share was active 4 weeks later?\n\nTables: `users(id, signup_date)` and `events(user_id, event_date)`. The events table has 2 billion rows.'),
      mc('First decide the grain of the result. One row per…', ['Signup week', 'Event', 'User and day', 'Table'], 'Each cohort gets one row with its size and its retention.'),
      mc('events has many rows per user per day. Before joining it to users you should…', ['Reduce it to distinct user and week', 'Join first and deduplicate at the end', 'Delete old events', 'Add an ORDER BY'], 'It prevents fan-out and makes the join far smaller.'),
      fillc('SELECT DATE_TRUNC(\'week\', signup_date) AS cohort, COUNT(*) AS n_users\nFROM users\nGROUP BY ___;', ['1', 'n_users', 'id', '*'], 'GROUP BY 1 groups by the first selected expression.'),
      info('Building it in steps', 'Use CTEs:\n\n1. `cohorts`: each user with their signup week.\n2. `activity`: distinct user and active week.\n3. Join them on the user, matching the active week to the signup week plus 4.\n4. Count retained users per cohort and divide by the cohort size.'),
      mc('Users with no activity in week 4 must still count in the denominator. Which join from cohorts to activity?', ['LEFT JOIN', 'INNER JOIN', 'CROSS JOIN', 'No join at all'], 'An inner join would drop exactly the users who were not retained.'),
      mc('The "week 4" condition on the activity table belongs…', ['In the ON clause, so unmatched users are kept', 'In WHERE, so unmatched users are removed', 'In ORDER BY', 'In LIMIT'], 'In WHERE it would turn the left join into an inner join.'),
      type('A cohort has 200 users and 50 were active in week 4. What is the retention in percent?', ['25', '25%'], '50 / 200.'),
      mc('The query takes an hour. The events table is partitioned by date. Easy win?', ['Filter events to the date range you need, so only those partitions are read', 'Select every column', 'Remove the GROUP BY', 'Run it twice'], 'Partition pruning skips most of the 2 billion rows.')),

    L('Interview drill: SQL',
      info('What gets asked', 'The classics: second-highest salary, top n per group, running totals, duplicates, "users who did A but not B".\n\nFollow-ups: "What about ties?", "What about NULLs?", "How would you speed it up?"'),
      order('Second-highest salary', ['SELECT MAX(salary)', 'FROM employees', 'WHERE salary < (', '  SELECT MAX(salary) FROM employees', ');'], 'The largest salary below the maximum, which also handles ties at the top.'),
      order('Find duplicated emails', ['SELECT email, COUNT(*) AS n', 'FROM users', 'GROUP BY email', 'HAVING COUNT(*) > 1;'], 'Group, then keep the groups with more than one row.'),
      mc('"Delete duplicates but keep one row per email." How do you identify the rows to delete?', ['ROW_NUMBER() OVER (PARTITION BY email ORDER BY id), then delete rows numbered above 1', 'DISTINCT inside the DELETE', 'ORDER BY email', 'A CROSS JOIN'], 'Row number 1 is the keeper in each group.'),
      info('Order of execution', 'SQL is written SELECT first, but it **runs** in this order:\n\nFROM and JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT.\n\nThis explains why WHERE cannot use an aggregate or an alias defined in SELECT.'),
      order('Order the logical execution of a query', ['FROM and JOIN', 'WHERE', 'GROUP BY', 'HAVING', 'SELECT', 'ORDER BY', 'LIMIT'], 'Rows are gathered, filtered, grouped, filtered again, projected, sorted and cut.'),
      mc('"WHERE or HAVING for a filter on a plain column?"', ['WHERE, because rows are removed before grouping', 'HAVING, because it runs later', 'They always cost the same', 'Neither can filter a plain column'], 'Less data reaches the expensive grouping step.'),
      match('Match the follow-up to the answer', [['"What about ties?"', 'Choose between RANK, DENSE_RANK and ROW_NUMBER'], ['"Why is it slow?"', 'Read the plan with EXPLAIN and look for full scans'], ['"When does an index hurt?"', 'On write-heavy tables: every insert updates it'], ['"What about missing values?"', 'Decide explicitly with COALESCE or IS NULL']]),
      mc('An index on `created_at` is not used by `WHERE DATE(created_at) = \'2025-01-01\'`. Why?', ['The function wrapped around the column hides it from the index', 'Dates cannot be indexed', 'The index is too new', 'WHERE never uses indexes'], 'Compare a range on the raw column instead.'))
  ],

  stats: [
    L('Describing data and chance',
      info('Centre and spread', '**Mean:** the average. **Median:** the middle value, robust to outliers. **Standard deviation:** typical distance from the mean.\n\nSalaries 3, 3, 4, 5, 100: mean 23, median 4. The median describes a typical person far better.'),
      type('What is the median of 7, 1, 3, 9, 5?', ['5'], 'Sorted: 1, 3, 5, 7, 9.'),
      mc('Which is least affected by one extreme value?', ['Median', 'Mean', 'Range', 'Standard deviation'], 'The middle value does not move.'),
      info('Probability', 'Probability runs from 0 (impossible) to 1 (certain).\n\n- **And**, for independent events: multiply. Two heads: 0.5 × 0.5.\n- **Or**, for exclusive events: add.\n- **Not:** 1 minus the probability.'),
      type('A fair coin is tossed 3 times. Probability of 3 heads, as a fraction?', ['1/8', '0.125'], '0.5 × 0.5 × 0.5.'),
      type('The chance of rain is 0.3. What is the chance of no rain?', ['0.7', '.7', '70%'], '1 - 0.3.'),
      mc('Two events are independent when…', ['Knowing one tells you nothing about the other', 'They cannot both happen', 'They always happen together', 'Their probabilities add to 1'], 'Events that cannot both happen are "mutually exclusive", a different idea.'),
      match('Match the distribution to an example', [['Binomial', 'Conversions out of n visitors'], ['Poisson', 'Support calls per hour'], ['Normal', 'Average of many measurements'], ['Exponential', 'Time until the next event']])),

    L('Conditional probability and Bayes',
      info('Given that…', '**P(A | B)** is the probability of A given that B happened.\n\n**Bayes’ rule** turns it around:\n\n```\nP(A | B) = P(B | A) · P(A) / P(B)\n```\n\nIt explains a famous surprise about medical tests.'),
      info('The rare-disease surprise', '1 in 100 people has a condition. The test catches 99% of real cases and wrongly flags 5% of healthy people.\n\nOut of 10,000 people: 100 are ill, 99 test positive. 9,900 are healthy, 495 test positive.\n\nPositive tests: 99 + 495 = 594. Only **99 / 594 ≈ 17%** are really ill.'),
      mc('Why is the chance so low despite a "99% accurate" test?', ['Healthy people vastly outnumber ill people, so false positives dominate', 'The test is broken', 'Bayes’ rule is approximate', '99% is a typo'], 'The base rate matters.'),
      type('Prior 0.5, sensitivity 0.9, false-positive rate 0.1. What is P(ill | positive)?', ['0.9', '.9', '90%'], '0.45 / (0.45 + 0.05).'),
      fillc('true_pos = prior * sensitivity\nfalse_pos = (1 - prior) * (1 - ___)\nposterior = true_pos / (true_pos + false_pos)', ['specificity', 'sensitivity', 'prior', 'posterior'], 'The false-positive rate is 1 minus specificity.'),
      mc('A spam filter flags an email. To know the chance it is really spam you also need…', ['The base rate of spam', 'The email length', 'The sender’s age', 'Nothing more'], 'The prior, P(spam).'),
      tf('P(A | B) is always equal to P(B | A).', false, 'Confusing them is the "prosecutor’s fallacy".'),
      mc('In ML terms, the prior corresponds to…', ['Class frequency before seeing the features', 'The learning rate', 'The test accuracy', 'The loss'], 'Imbalanced classes are a base-rate problem.')),

    L('Samples, tests and intervals',
      info('From a sample to a claim', 'We measure a **sample** and want to say something about everyone.\n\nThe **central limit theorem**: the average of many independent observations is approximately normal, whatever the original distribution. That is why tests on averages work.'),
      mc('Larger samples give…', ['Narrower confidence intervals', 'Wider confidence intervals', 'The same interval', 'A different mean by design'], 'Uncertainty shrinks with the square root of n.'),
      info('Hypothesis tests', 'Start by assuming **nothing changed** (the null hypothesis). The **p-value** is the probability of seeing data at least this extreme if that were true.\n\nSmall p (commonly below 0.05): luck is an unlikely explanation.\n\nIt is **not** the probability that the null is true.'),
      mc('p = 0.03 means…', ['If there were no real effect, a result this extreme would occur about 3% of the time', 'There is a 3% chance the effect is real', 'The effect is 3% large', '97% of users prefer B'], 'A statement about the data, assuming no effect.'),
      match('Match the error', [['Type I', 'False positive: claiming an effect that is not there'], ['Type II', 'False negative: missing a real effect'], ['Power', 'Chance of detecting a real effect'], ['Alpha', 'The false-positive rate you accept']]),
      type('You test 20 unrelated metrics at alpha = 0.05 with no real effects. How many false positives do you expect?', ['1'], '20 × 0.05.'),
      mc('A 95% confidence interval for a lift is [-0.5%, +3%]. Conclusion?', ['Not conclusive: zero is inside the interval', 'B is certainly better', 'B is certainly worse', 'The test is invalid'], 'You need more data or must accept the uncertainty.'),
      tf('A statistically significant result is always practically important.', false, 'With huge samples, tiny effects become significant. Look at the effect size.')),

    L('A/B testing and interview level',
      info('Designing a test', '1. One **primary metric** and a minimum effect worth detecting.\n2. **Sample size** for that effect (power, usually 80%).\n3. **Randomise** by user.\n4. Run for full weeks. **Do not stop early** because it looks good.\n5. Analyse, report the interval, check guardrails.'),
      order('Order an A/B test', ['Define the metric and the minimum effect', 'Compute the required sample size', 'Randomly assign users', 'Run for the planned duration', 'Analyse and decide'], 'Decide the rules before you see the data.'),
      mc('Checking results daily and stopping when p < 0.05 is a problem because…', ['It inflates the false-positive rate', 'It wastes electricity', 'It lowers power', 'It is fine'], 'This is "peeking". Use a fixed horizon or a sequential method.'),
      mc('Why randomise by user and not by visit?', ['So the same person always sees the same version', 'It is faster', 'Visits are not measurable', 'To reduce the sample size'], 'Otherwise users see both versions and observations are not independent.'),
      mc('Clicks rise right after launch then return to normal. This is the…', ['Novelty effect', 'Simpson’s paradox', 'Survivorship bias', 'Central limit theorem'], 'People try new things. Run long enough to see steady behaviour.'),
      mc('B is better overall, but worse in every country when split. Name?', ['Simpson’s paradox', 'Novelty effect', 'Type II error', 'Regression to the mean'], 'Group sizes differ between versions. Check the mix.'),
      mc('Correlation between ice-cream sales and drowning is explained by…', ['A confounder: hot weather', 'Ice cream causing drowning', 'Drowning causing ice-cream sales', 'Chance only'], 'A third variable drives both.'),
      order('Order a strong answer to "How do you establish causation?"', ['Correlation alone is not enough', 'Confounders or reverse causality may explain it', 'A randomised experiment is the clean answer', 'Otherwise use causal-inference methods and state assumptions'], 'Experiment when you can.'),
      tf('Guardrail metrics are metrics that must not get worse, such as latency or revenue.', true, 'A win on the primary metric that breaks a guardrail is not a win.')),

    L('Expectation, variance and choosing a test',
      info('Expected value and variance', 'The **expected value** is the long-run average: the sum of each outcome times its probability.\n\n**Variance** is the expected squared distance from the mean; the **standard deviation** is its square root.\n\nFor independent variables, variances add: Var(X + Y) = Var(X) + Var(Y).'),
      type('A game pays 10 with probability 0.2 and nothing otherwise. What is the expected payout?', ['2', '2.0'], '10 × 0.2.'),
      type('The standard deviation of a variable is 3. What is its variance?', ['9'], 'Variance is the standard deviation squared.'),
      info('Standard error', 'The mean of n observations varies less than a single observation:\n\n```\nstandard error = sd / sqrt(n)\n```\n\nA rough 95% confidence interval is the mean ± 2 standard errors. To halve the interval you need **four** times the data.'),
      type('sd = 10 and n = 100. What is the standard error of the mean?', ['1', '1.0'], '10 / sqrt(100).'),
      type('You want a confidence interval half as wide. By what factor must the sample size grow?', ['4', '4x', 'four'], 'The width shrinks with the square root of n.'),
      match('Match the question to the test', [['Do two groups differ in their mean?', 't-test'], ['Do two groups differ in a conversion rate?', 'Two-proportion z-test'], ['Do more than two groups differ in their mean?', 'ANOVA'], ['Is skewed data shifted, without assuming normality?', 'Mann-Whitney U test']]),
      mc('A correlation of 0 between X and Y means…', ['No linear relationship, although a curved one may exist', 'X and Y are independent', 'X causes Y', 'The data is wrong'], 'Correlation only measures straight-line association.'),
      tf('About 95% of a normal distribution lies within 2 standard deviations of the mean.', true, 'About 68% lies within 1 and 99.7% within 3.')),

    L('Common mistakes and debugging',
      info('Ways to fool yourself', '- **Multiple comparisons:** test 20 things and one "wins" by luck.\n- **p-hacking:** try metrics, segments and cut-offs until p < 0.05.\n- **Survivorship bias:** looking only at those who remained.\n- **Regression to the mean:** extreme values are followed by more ordinary ones.'),
      type('You test 10 metrics and want an overall alpha of 0.05. With the Bonferroni correction, what alpha does each test use?', ['0.005', '.005'], '0.05 / 10.'),
      mc('A study of successful start-ups finds that all took big risks and concludes that risk causes success. The flaw?', ['Survivorship bias: the risk-takers that failed are not in the sample', 'Simpson’s paradox', 'The sample is too large', 'The novelty effect'], 'You must also count those who took risks and disappeared.'),
      mc('The 10 worst-performing shops get a training course and improve next quarter. Why be careful?', ['Regression to the mean: extreme results drift back without any intervention', 'Training never works', 'The novelty effect', 'The shops were randomised'], 'Compare with similar shops that did not get the course.'),
      info('A/B test bugs', '- **Sample ratio mismatch:** a planned 50/50 split arrives as 52/48. Assignment or logging is broken; do not trust the result.\n- **Wrong unit:** randomise by user but analyse page views, and the test looks more certain than it is.\n- **A/A test:** run two identical versions first; if they "differ", the pipeline has a bug.'),
      mc('A 50/50 test has 100,000 users in A and 92,000 in B. What do you do?', ['Stop and investigate assignment and logging before reading any metric', 'Declare A the winner because it is larger', 'Ignore it, because it is close enough', 'Remove 8,000 users from A at random'], 'A gap that large cannot be chance, so one group has lost users in a biased way.'),
      mc('You randomise by user but compute the p-value as if every page view were independent. Effect?', ['The interval is too narrow and false positives rise', 'The interval is too wide', 'No effect', 'The lift changes sign'], 'Views from the same user are correlated, so there is less information than the count suggests.'),
      fillc('lift = (conv_b - conv_a) / ___', ['conv_a', 'conv_b', 'n_users', '100'], 'Relative lift is measured against the control.'),
      tf('A non-significant result proves that there is no effect.', false, 'It may only mean that the test had too little power.')),

    L('Case study: testing a new checkout page',
      info('The situation', 'An online shop converts 5% of its visitors into buyers. The design team has a new checkout page and believes it converts better. You own the experiment.\n\nAbout 20,000 visitors arrive per day.'),
      mc('What is the primary metric?', ['Conversion rate per user', 'Number of page views', 'Time spent on the page', 'Number of designs tried'], 'It is the outcome the change is meant to move.'),
      mc('Before computing a sample size you must ask the business for…', ['The smallest lift worth shipping', 'The colour of the button', 'The p-value they would like to see', 'The expected winner'], 'Smaller effects need far more data to detect.'),
      info('Sample size', 'A common rule of thumb for 80% power at alpha 0.05:\n\n```\nn per group ≈ 16 · p · (1 - p) / d²\n```\n\n`p` is the baseline rate and `d` the absolute difference to detect. Halving `d` multiplies the sample by four.'),
      type('p = 0.05 and d = 0.01. Using n ≈ 16 · p · (1 − p) / d², how many users per group?', ['7600', '7,600'], '16 × 0.0475 / 0.0001.'),
      mc('That is 15,200 users, less than one day of traffic. How long do you run the test?', ['At least one full week, to cover weekday and weekend behaviour', 'Six hours', 'Until p drops below 0.05', 'Exactly as long as it takes to reach 15,200 users'], 'Shoppers on a Tuesday morning differ from those on a Sunday night.'),
      mc('Result: 5.0% against 5.6%, with a 95% interval for the difference of [0.2%, 1.0%]. But page load time rose by 400 ms. Decision?', ['Hold: a guardrail got worse, so fix the speed and retest or weigh the trade-off explicitly', 'Ship at once', 'Declare the test invalid', 'Rerun until the latency looks fine'], 'A win on the primary metric does not cancel a broken guardrail.'),
      mc('The lift is +3% on desktop and −1% on mobile. Sensible next step?', ['Treat it as a hypothesis and confirm it with a new test on mobile', 'Ship to desktop and report the split as proven', 'Ignore segments for ever', 'Average the two numbers'], 'Segments found after the fact are multiple comparisons.'),
      order('Order your final report', ['The decision and the headline lift with its interval', 'How the test was set up: metric, sample, duration', 'Guardrail results and the split-ratio check', 'Caveats and segment observations', 'The recommended next step'], 'Lead with the decision; evidence follows.')),

    L('Interview drill: statistics',
      info('What gets asked', '"Explain a p-value to a product manager." "What is a confidence interval?" "How would you size a test?" "The test is flat: now what?"\n\nInterviewers listen for precise wording, and for whether you connect the statistics to a decision.'),
      mc('Best plain-language explanation of a p-value?', ['If the change did nothing, how often we would see a difference at least this large by luck', 'The chance that the new version is better', 'The chance that we made a mistake', 'The size of the improvement'], 'It always assumes "no effect" and talks about the data.'),
      mc('Correct reading of "a 95% confidence interval"?', ['The method captures the true value in 95% of repeated experiments', 'There is a 95% chance that the sample mean is inside', '95% of the data lies inside', 'The effect is 95% large'], 'The 95% describes the procedure, not one particular interval.'),
      mc('"What determines the sample size of a test?"', ['The variance of the metric, the minimum effect, alpha and power', 'Only the traffic you have', 'The number of metrics', 'The p-value you observe'], 'All four are fixed before the test starts.'),
      info('Probability puzzles', 'Short puzzles test whether you set up the sample space. Write the cases down, use the complement ("at least one" = 1 − "none"), and state your assumptions: fair, independent.'),
      type('Two fair dice are rolled. What is the probability that the sum is 7? Answer as a fraction.', ['1/6', '6/36'], '6 of the 36 outcomes sum to 7.'),
      type('A fair coin is tossed twice. What is the probability of at least one head? Answer as a fraction.', ['3/4', '0.75', '75%'], '1 − 1/4, the chance of two tails.'),
      match('Match the follow-up to the answer', [['"The test is flat. Now what?"', 'Check power and the interval before saying "no effect"'], ['"Can we stop early?"', 'Only with a sequential method planned in advance'], ['"We cannot randomise."', 'Use a quasi-experiment such as difference-in-differences'], ['"The metric is very skewed."', 'Bootstrap, transform or cap the outliers']]),
      order('Order a strong answer to "Explain the central limit theorem and why it matters"', ['Averages of many independent observations are approximately normal', 'This holds whatever the shape of the original data', 'The spread of the average shrinks with the square root of n', 'So we can build intervals and tests for means and rates'], 'Statement, generality, rate, use.'))
  ]
};
